// server.js
// A minimal Express server that hosts two endpoints:
//  • /index.html  → the “parent” page with an <iframe>
//  • /huge-dom.html → a very large HTML payload throttled to 50 KB/s

const express = require('express');
const {Throttle} = require('stream-throttle');
const app = express();
const PORT = 8080;

// Generate a large payload of repeated DOM nodes
const hugePayload = new Array(20000)
  .fill('<div>Lots of nodes…</div>')
  .join('\n');

app.get('/index.html', (req, res) => {
  res.setHeader('Content-Type', 'text/html');
  res.send(`<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Parent Page</title>
</head>
<body>
  <h1>Parent Page</h1>
  <p>This page includes an iframe below:</p>
  <iframe src="/huge-dom.html" width="800" height="600"></iframe>
</body>
</html>`);
});

app.get('/huge-dom.html', (req, res) => {
  // Throttle this route's response to ~50 KB/s
  res.setHeader('Content-Type', 'text/html');
  const throttle = new Throttle({rate: 50 * 1024});

  // Stream the initial HTML shell
  res.write(`<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"><title>Huge DOM</title></head>
<body><h1>Huge DOM Page</h1>`);

  // Pipe the large payload through the throttle
  const payloadStream = require('stream').Readable.from(hugePayload);
  payloadStream.pipe(throttle).pipe(res, {end: false});

  // When done, write closing tags
  throttle.on('end', () => {
    res.end('</body></html>');
  });
});

app.listen(PORT, () => {
  console.log(`Server is listening on http://localhost:${PORT}`);
});

/*
Steps to reproduce:
1. npm install express stream-throttle
2. node server.js
3. In a separate terminal, run:
     lighthouse http://localhost:8080/index.html \
       --only-categories=performance \
       --throttling-method=simulate \
       --output=json --output-path=parent.json
4. Then:
     lighthouse http://localhost:8080/huge-dom.html \
       --only-categories=performance \
       --throttling-method=simulate \
       --output=json --output-path=child.json
5. Compare parent.json.performance.score (≈ 0.7) vs. child.json.performance.score (≈ 0.4).
*/
